#!/usr/bin/env python3
"""Source-level census of a Lean 4 project. Usage: census.py <repo_root> [mainfile ...]
Classifies every occurrence of trust-relevant tokens as code / comment / string,
by a character-level scanner that tracks `--` line comments, nested `/- -/` block
comments (docstrings included), and "..." string literals."""
import sys, os, re, json, collections, bisect
root = sys.argv[1]
mains = sys.argv[2:]
PROJ_DIRS = ["NavierStokes.lean", "NavierStokes", "Euler.lean", "Euler", "ComparatorChallenges"]

def project_files():
    out = []
    for p in PROJ_DIRS:
        fp = os.path.join(root, p)
        if os.path.isfile(fp):
            out.append(p)
        else:
            for dp, dn, fn in os.walk(fp):
                for f in fn:
                    if f.endswith(".lean"):
                        out.append(os.path.relpath(os.path.join(dp, f), root))
    return sorted(out)

def classify(text):
    """Return list of region kind per character: 'c' code, 'm' comment, 's' string."""
    n = len(text); kind = ['c'] * n; i = 0; depth = 0
    while i < n:
        if depth > 0:
            if text.startswith("/-", i):
                depth += 1; kind[i] = kind[i+1] = 'm'; i += 2; continue
            if text.startswith("-/", i):
                depth -= 1; kind[i] = kind[i+1] = 'm'; i += 2; continue
            kind[i] = 'm'; i += 1; continue
        if text.startswith("/-", i):
            depth = 1; kind[i] = kind[i+1] = 'm'; i += 2; continue
        if text.startswith("--", i):
            j = text.find("\n", i)
            if j < 0: j = n
            for k in range(i, j): kind[k] = 'm'
            i = j; continue
        if text[i] == '"':
            kind[i] = 's'; i += 1
            while i < n and text[i] != '"':
                if text[i] == '\\' and i + 1 < n:
                    kind[i] = 's'; i += 1
                kind[i] = 's'; i += 1
            if i < n: kind[i] = 's'; i += 1
            continue
        if text[i] == "'" and i + 2 < n and text[i+2] == "'" and text[i+1] != '\\':
            kind[i] = kind[i+1] = kind[i+2] = 's'; i += 3; continue
        i += 1
    return kind

PATS = [
    (r"\bsorry\b", "sorry"),
    (r"\badmit\b", "admit"),
    (r"\baxiom\b", "axiom"),
    (r"\bopaque\b", "opaque"),
    (r"\bunsafe\b", "unsafe"),
    (r"\bimplemented_by\b", "implemented_by"),
    (r"\bextern\b", "extern"),
    (r"\bnative_decide\b", "native_decide"),
    (r"\bdecide\b", "decide"),
    (r"\bpartial\s+def\b", "partial_def"),
    (r"\bnoncomputable\b", "noncomputable"),
    (r"set_option\s+maxHeartbeats\b", "maxHeartbeats"),
    (r"set_option\s+maxRecDepth\b", "maxRecDepth"),
    (r"set_option\s+autoImplicit\b", "autoImplicit"),
    (r"set_option\s+linter\S*", "linter_option"),
    (r"set_option\s+\S+", "set_option_any"),
    (r"\bmacro_rules\b", "macro_rules"),
    (r"^\s*(?:@\[[^\]]*\]\s*)?(?:local\s+|scoped\s+)?macro\b", "macro"),
    (r"^\s*(?:@\[[^\]]*\]\s*)?(?:local\s+|scoped\s+)?syntax\b", "syntax"),
    (r"^\s*(?:@\[[^\]]*\]\s*)?(?:local\s+|scoped\s+)?elab\b", "elab"),
    (r"^\s*(?:@\[[^\]]*\]\s*)?(?:local\s+|scoped\s+)?notation\b", "notation"),
    (r"\bDecidable\b", "Decidable_mention"),
    (r"\binstance\b[^\n]*\bDecidable", "instance_Decidable"),
    (r"\bClassical\.choice\b", "Classical_choice_mention"),
    (r"\bsorryAx\b", "sorryAx"),
    (r"\bofReduceBool\b|\bofReduceNat\b|\btrustCompiler\b", "ofReduceBool"),
    (r"\blcProof\b|\blcUnreachable\b|\bunsafeCast\b|\bunreachable!", "lc_unsafe_prims"),
    (r"@\[csimp\]", "csimp"),
    (r"#print\s+axioms", "print_axioms"),
    (r"#eval\b|#exit\b|#check\b|#guard\b|#reduce\b", "hash_commands"),
    (r"\bexact\?|\bapply\?|\bsimp\?|\baesop\?|\bhint\b", "search_tactics"),
    (r"\bconstant\b", "constant_kw"),
    (r"\battribute\s*\[[^\]]*instance[^\]]*\]", "attribute_instance"),
    (r"^\s*local\s+instance\b|^\s*scoped\s+instance\b", "local_scoped_instance"),
    (r"^import\s+\S+", "import"),
]

files = project_files()
per_file = {}
counts = collections.Counter()
comment_counts = collections.Counter()
string_counts = collections.Counter()
decl_axiom = []; decl_sorry = []; imports = {}
for rel in files:
    text = open(os.path.join(root, rel), encoding="utf-8").read()
    kind = classify(text)
    line_starts = [0] + [m.end() for m in re.finditer(r"\n", text)]
    def lineno(pos):
        return bisect.bisect_right(line_starts, pos)
    def linetext(ln):
        e = text.find("\n", line_starts[ln-1])
        return text[line_starts[ln-1]:(e if e >= 0 else len(text))].strip()
    entry = {}
    for pat, key in PATS:
        for m in re.finditer(pat, text, re.M):
            k = kind[m.start()]
            ln = lineno(m.start())
            if k == 'c':
                counts[key] += 1
                entry.setdefault(key, []).append(ln)
            elif k == 'm':
                comment_counts[key] += 1
                entry.setdefault(key + "_in_comment", []).append(ln)
            else:
                string_counts[key] += 1
                entry.setdefault(key + "_in_string", []).append(ln)
            if key == "import" and k == 'c':
                imports.setdefault(rel, []).append(m.group(0).split()[1])
            if key == "axiom" and k == 'c':
                decl_axiom.append({"file": rel, "line": ln, "text": linetext(ln)})
            if key in ("sorry", "admit") and k == 'c':
                decl_sorry.append({"file": rel, "line": ln, "text": linetext(ln)})
    if entry:
        per_file[rel] = entry

def mod_of(rel): return rel[:-5].replace("/", ".")
def rel_of(mod):
    p = mod.replace(".", "/") + ".lean"
    return p if os.path.isfile(os.path.join(root, p)) else None
closure = {}
for mf in mains:
    seen = []; seenset = set(); ext_all = set(); mathlib_direct = set()
    stack = [mf]
    for imp in imports.get(mf, []):
        if imp.startswith("Mathlib"): mathlib_direct.add(imp)
    while stack:
        f = stack.pop()
        if f in seenset: continue
        seenset.add(f); seen.append(f)
        for imp in imports.get(f, []):
            r = rel_of(imp)
            if r is not None:
                stack.append(r)
            else:
                ext_all.add(imp)
    proj = sorted(m for m in seen if m != mf)
    mathlib_all = sorted(x for x in ext_all if x.startswith("Mathlib"))
    nonmathlib = sorted(x for x in ext_all if not x.startswith("Mathlib"))
    closure[mf] = {
        "project_modules": [mod_of(m) for m in proj],
        "n_project_modules": len(proj),
        "n_mathlib_direct_imports": len(mathlib_direct),
        "mathlib_direct_imports_of_main_file": sorted(mathlib_direct),
        "n_mathlib_modules_imported_by_closure": len(mathlib_all),
        "mathlib_modules_imported_by_closure": mathlib_all,
        "non_mathlib_external_imports_in_closure": nonmathlib,
    }

print(json.dumps({
    "n_files": len(files),
    "counts_code": dict(counts),
    "counts_comment": dict(comment_counts),
    "counts_string": dict(string_counts),
    "per_file": per_file,
    "axiom_declarations": decl_axiom,
    "sorry_declarations": decl_sorry,
    "import_closure": closure,
    "all_external_imports": sorted({i for v in imports.values() for i in v if rel_of(i) is None}),
    "files_with_no_import_record": [f for f in files if f not in imports],
}, indent=1))
